\set ON_ERROR_STOP on
begin;
create schema vet_test;
create function vet_test.ok(condition boolean,label text) returns void language plpgsql as $$begin if condition is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function vet_test.denied(statement text,expected text) returns void language plpgsql as $$declare msg text;begin
 begin execute statement;exception when others then get stacked diagnostics msg=MESSAGE_TEXT; if position(expected in msg)>0 then raise notice 'PASS: rejected %',expected;return;end if;raise exception 'Wrong rejection: % (expected %)',msg,expected;end;
 raise exception 'FAIL: operation was allowed: %',statement;
end$$;
grant usage on schema vet_test to authenticated;
grant execute on all functions in schema vet_test to authenticated;
create temp table vet_ids(key text primary key,val uuid,j jsonb);
grant all on vet_ids to authenticated;
create function vet_test.payload() returns jsonb language sql as $$select jsonb_build_object('owner',jsonb_build_object('name','Pilot Owner','contact_details','Québec test'),'agent',jsonb_build_object('name','Écurie test','email','agent@example.test'),'administrations',jsonb_build_array(jsonb_build_object('product','Produit test','manufacturer','Fabricant test','lot','LOT-1','administered_on',current_date-1,'product_expires_on',current_date+10,'valid_until',current_date+100,'diseases',jsonb_build_array('influenza','ehv_1','ehv_4'))))$$;
grant execute on function vet_test.payload() to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select public.vet_admin_save_issuer('a1000000-0000-0000-0000-000000000001','Clinique A','clinic','Québec test','active');
select public.vet_admin_save_issuer('a1000000-0000-0000-0000-000000000002','Clinique B','clinic','Québec test','active');
select public.vet_admin_set_member('a1000000-0000-0000-0000-000000000001','phase1.org-a-secretary@example.test');
select public.vet_admin_set_member('a1000000-0000-0000-0000-000000000002','phase1.org-b-admin@example.test');
select public.vet_admin_settings(true,24);
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
select vet_test.denied($q$select public.vet_add_practitioner('a1000000-0000-0000-0000-000000000001','Amelie Croteau','4887')$q$,'VET_ACCESS_DENIED');
select vet_test.ok((select count(*)=0 from public.vet_issuers where id in ('a1000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000002')),'ordinary HSP account refused');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
insert into vet_ids(key,val) values('practitioner',public.vet_add_practitioner('a1000000-0000-0000-0000-000000000001','Amelie Croteau','4887'));
select public.vet_save_draft('a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001',1,(select val from vet_ids where key='practitioner'),vet_test.payload());
select vet_test.denied($q$select public.vet_create_horse('a1000000-0000-0000-0000-000000000001','Test','Owner','Name','a@example.test')$q$,'permission denied');
select vet_test.denied($q$select public.vet_create_searched_horse('a2000000-0000-0000-0000-000000000001',gen_random_uuid(),'Pilot','Owner')$q$,'VET_SEARCH_REQUIRED');
select vet_test.denied($q$select public.vet_search_horse_candidates('a2000000-0000-0000-0000-000000000001','Pilot Horse','','','')$q$,'VET_SEARCH_CRITERIA_REQUIRED');
insert into vet_ids(key,j) values('search',public.vet_search_horse_candidates('a2000000-0000-0000-0000-000000000001','Pilot Horse','Pilot Owner','REG-TEST-2026','123456789012345'));
select vet_test.ok(jsonb_array_length((select j->'results' from vet_ids where key='search'))=0,'targeted search finds absent horse without association');
insert into vet_ids(key,j) values('created',public.vet_create_searched_horse('a2000000-0000-0000-0000-000000000001',(select (j->>'search_id')::uuid from vet_ids where key='search'),'Pilot','Owner','vet-pilot-owner@example.test'));
insert into vet_ids(key,val) select 'horse',(j#>>'{certificate,horse_id}')::uuid from vet_ids where key='created';
select vet_test.ok((select j#>>'{certificate,payload,horse,name}'='Pilot Horse' from vet_ids where key='created'),'new horse immediately linked');
select vet_test.ok((select j#>>'{certificate,payload,administrations,0,lot}'='LOT-1' from vet_ids where key='created'),'vaccine payload preserved through creation');
select vet_test.ok((select j#>>'{certificate,payload,agent,email}'='agent@example.test' from vet_ids where key='created'),'agent data preserved');
select vet_test.denied($q$select public.vet_create_searched_horse('a2000000-0000-0000-0000-000000000001',gen_random_uuid(),'Pilot','Owner')$q$,'VET_SEARCH_REQUIRED');
select vet_test.ok((select count(*)=0 from public.horses where id=(select val from vet_ids where key='horse')),'no indirect central horse access');
reset role;
insert into vet_ids(key,val) select 'owner',primary_owner_contact_id from public.horses where id=(select val from vet_ids where key='horse');
set local role authenticated;
insert into vet_ids(key,j) values('reuse_owner_search',public.vet_search_horse_candidates('a2000000-0000-0000-0000-000000000001','Second Pilot Horse','Pilot Owner','',''));
insert into vet_ids(key,j) values('reuse_owner',public.vet_create_searched_horse('a2000000-0000-0000-0000-000000000001',(select (j->>'search_id')::uuid from vet_ids where key='reuse_owner_search'),'Pilot','Owner','vet-pilot-owner@example.test'));
reset role;
select vet_test.ok((select primary_owner_contact_id=(select val from vet_ids where key='owner') from public.horses where id=(select (j#>>'{certificate,horse_id}')::uuid from vet_ids where key='reuse_owner')),'unique matching owner email reuses central contact');
set local role authenticated;
insert into vet_ids(key,j) values('late_search',public.vet_search_horse_candidates('a2000000-0000-0000-0000-000000000001','Late Pilot Horse','Pilot Owner','',''));
reset role;
insert into public.horses(name,primary_owner_contact_id,created_by_user_id) values('Late Pilot Horse',(select val from vet_ids where key='owner'),null);
set local role authenticated;
insert into vet_ids(key,j) values('late_match',public.vet_create_searched_horse('a2000000-0000-0000-0000-000000000001',(select (j->>'search_id')::uuid from vet_ids where key='late_search'),'Pilot','Owner','vet-pilot-owner@example.test'));
select vet_test.ok((select (j->>'needs_confirmation')::boolean from vet_ids where key='late_match'),'new match after original search requires confirmation before creation');
reset role;
update public.vet_horse_searches set expires_at=now()-interval '1 minute' where id=(select (j->>'search_id')::uuid from vet_ids where key='late_search');
set local role authenticated;
select vet_test.denied($q$select public.vet_create_searched_horse('a2000000-0000-0000-0000-000000000001',(select (j->>'search_id')::uuid from vet_ids where key='late_search'),'Pilot','Owner')$q$,'VET_SEARCH_REQUIRED');
insert into vet_ids(key,j) values('strong_search',public.vet_search_horse_candidates('a2000000-0000-0000-0000-000000000001','Pilot Horse','Pilot Owner','','123456789012345'));
insert into vet_ids(key,j) values('strong_match',public.vet_create_searched_horse('a2000000-0000-0000-0000-000000000001',(select (j->>'search_id')::uuid from vet_ids where key='strong_search'),'Pilot','Owner','vet-pilot-owner@example.test'));
select vet_test.denied($q$select public.vet_create_searched_horse('a2000000-0000-0000-0000-000000000001',(select (j->>'search_id')::uuid from vet_ids where key='strong_search'),'Pilot','Owner','vet-pilot-owner@example.test',(select j->>'reviewed_matches' from vet_ids where key='strong_match'),'Un cheval différent confirmé')$q$,'VET_DUPLICATE_IDENTIFIER');

select vet_test.denied($q$select public.vet_create_searched_horse('a2000000-0000-0000-0000-000000000001',(select (j->>'search_id')::uuid from vet_ids where key='search'),'Pilot','Owner','vet-pilot-owner@example.test')$q$,'VET_SEARCH_REQUIRED');
insert into vet_ids(key,j) values('found',public.vet_search_horse_candidates('a2000000-0000-0000-0000-000000000001','Pilot Horse','Pilot Owner','',''));
select vet_test.ok(jsonb_array_length((select j->'results' from vet_ids where key='found'))=1,'name and owner find existing horse');
select vet_test.ok((select j#>>'{results,0,identifiers}' like '%REG-TEST-2026%' from vet_ids where key='found'),'results include registration without association');
select public.vet_link_horse('a2000000-0000-0000-0000-000000000001',(select (j#>>'{results,0,selection_id}')::uuid from vet_ids where key='found'),true);
insert into vet_ids(key,j) values('duplicate',public.vet_create_searched_horse('a2000000-0000-0000-0000-000000000001',(select (j->>'search_id')::uuid from vet_ids where key='found'),'Pilot','Owner','vet-pilot-owner@example.test'));
select vet_test.ok((select (j->>'needs_confirmation')::boolean from vet_ids where key='duplicate'),'potential duplicate requires explicit confirmation');
select vet_test.denied($q$select public.vet_issue_certificate('a2000000-0000-0000-0000-000000000001')$q$,'VET_FRESH_VERIFICATION_REQUIRED');
select vet_test.denied($q$select public.vet_request_authorization((select val from vet_ids where key='practitioner'),repeat('a',64),'clinic_device')$q$,'VET_FRESH_VERIFICATION_REQUIRED');
select vet_test.denied($q$select public.vet_record_verification((select val from vet_ids where key='practitioner'),'Amelie Croteau','4887','Actif','verified')$q$,'permission denied');
reset role;
select vet_test.ok(public.vet_omvq_name_key('Dre Amélie Croteau m.v.')=public.vet_omvq_name_key('Amelie Croteau'),'OMVQ accents tolerated');
select vet_test.ok(public.vet_name_key('Amélie')<>public.vet_name_key('Amelie'),'central identity comparison unchanged');
select vet_test.denied($q$select public.vet_record_verification((select val from vet_ids where key='practitioner'),'Autre Personne','4887','Actif','verified')$q$,'VET_INVALID_POSITIVE');
select vet_test.denied($q$select public.vet_record_verification((select val from vet_ids where key='practitioner'),'Amelie Croteau','4887','Inactif','verified')$q$,'VET_INVALID_POSITIVE');
select public.vet_record_verification((select val from vet_ids where key='practitioner'),'Dre Amélie Croteau m.v.','4887','Actif','verified');
set local role authenticated;
select vet_test.denied($q$select public.vet_issue_certificate('a2000000-0000-0000-0000-000000000001')$q$,'VET_PRIOR_AUTHORIZATION_REQUIRED');
insert into vet_ids(key,val) values('authorization',public.vet_request_authorization((select val from vet_ids where key='practitioner'),repeat('a',64),'clinic_device'));
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select public.vet_set_signature_settings(30,1);
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select vet_test.denied($q$select public.vet_approve_authorization(repeat('a',64),'[[[0.1,0.1],[0.2,0.3],[0.3,0.1],[0.4,0.3],[0.5,0.1]]]',true)$q$,'permission denied');
select vet_test.denied($q$select token_hash from public.vet_signature_authorizations$q$,'permission denied');
reset role;
select vet_test.ok((public.vet_authorization_summary(repeat('a',64))->>'permit')='4887','personal summary contains verified veterinarian');
select vet_test.ok((public.vet_authorization_summary(repeat('a',64))->>'valid_days')::integer=365,'mandate terms cannot change after request');
select vet_test.ok(not(public.vet_authorization_summary(repeat('a',64)) ? 'token_hash'),'summary omits token hash');
select vet_test.ok(length(public.vet_authorization_summary(repeat('a',64))->>'authorized_account_name')>0,'consent names the authorized personal account');
select vet_test.denied($q$select public.vet_approve_authorization(repeat('a',64),'[]',true)$q$,'VET_SIGNATURE_REQUIRED');
select public.vet_approve_authorization(repeat('a',64),'[[[0.1,0.1],[0.2,0.3],[0.3,0.1],[0.4,0.3],[0.5,0.1]]]',true);
select vet_test.denied($q$select public.vet_approve_authorization(repeat('a',64),'[[[0.1,0.1],[0.2,0.3],[0.3,0.1],[0.4,0.3],[0.5,0.1]]]',true)$q$,'VET_AUTHORIZATION_LINK_INVALID');
set local role authenticated;
select public.vet_issue_certificate('a2000000-0000-0000-0000-000000000001');
select public.vet_issue_certificate('a2000000-0000-0000-0000-000000000001');
select vet_test.ok((select count(*)=3 from public.horse_vaccinations where certificate_id='a2000000-0000-0000-0000-000000000001'),'signed issuance idempotent: three disease records');
select vet_test.ok((select count(*)=1 from public.vet_certificate_signatures where certificate_id='a2000000-0000-0000-0000-000000000001'),'one signature per certificate');
select vet_test.ok((public.vet_get_certificate_health('a2000000-0000-0000-0000-000000000001')#>>'{influenza,status}')='valid','only signed certificate recognizes vaccination');
select vet_test.denied($q$select public.vet_delete_draft('a2000000-0000-0000-0000-000000000001')$q$,'VET_ISSUED_CERTIFICATE_REVOKE_REQUIRED');
select vet_test.denied($q$select public.vet_save_draft('a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001',1,(select val from vet_ids where key='practitioner'),vet_test.payload())$q$,'VET_DRAFT_CONFLICT');
reset role;
select vet_test.ok(public.vet_signature_intact('a2000000-0000-0000-0000-000000000001'),'content fingerprint and stored signature intact');
select vet_test.denied($q$update public.vet_certificates set payload='{}' where id='a2000000-0000-0000-0000-000000000001'$q$,'VET_CERTIFICATE_IMMUTABLE');
-- Detect even a privileged tamper to the signature evidence.
update public.vet_certificate_signatures set signed_content=jsonb_set(signed_content,'{payload,owner,name}','"Tampered"') where certificate_id='a2000000-0000-0000-0000-000000000001';
select vet_test.ok(not public.vet_signature_intact('a2000000-0000-0000-0000-000000000001'),'altered signed content detected');
select vet_test.ok((public.vet_evaluate_vaccinations((select val from vet_ids where key='horse'))#>>'{influenza,status}')<>'valid','tampered signature cannot recognize vaccination');
update public.vet_certificate_signatures set signed_content=(select snapshot#>'{signature,signed_content}' from public.vet_certificates where id='a2000000-0000-0000-0000-000000000001') where certificate_id='a2000000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000006',true);
select vet_test.ok((select count(*)=0 from public.vet_certificates where issuer_id='a1000000-0000-0000-0000-000000000001'),'other clinic cannot read certificate');
select vet_test.denied($q$select public.vet_delete_draft('a2000000-0000-0000-0000-000000000001')$q$,'VET_ACCESS_DENIED');
select vet_test.denied($q$select public.vet_cancel_authorization((select val from vet_ids where key='authorization'))$q$,'VET_ACCESS_DENIED');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
insert into vet_ids(key,val) select 'correction',(public.vet_correct_certificate('a2000000-0000-0000-0000-000000000001')).id;
select vet_test.ok((select signature_id is null and version_number=2 from public.vet_certificates where id=(select val from vet_ids where key='correction')),'correction is unsigned new version');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select vet_test.denied($q$select public.vet_issue_certificate((select val from vet_ids where key='correction'))$q$,'VET_PRIOR_AUTHORIZATION_REQUIRED');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select public.vet_issue_certificate((select val from vet_ids where key='correction'));
select vet_test.ok((select count(*)=2 from public.vet_certificate_signatures where issuer_id='a1000000-0000-0000-0000-000000000001'),'correction receives new automatic content-bound signature');
select vet_test.ok((select status='superseded' from public.vet_certificates where id='a2000000-0000-0000-0000-000000000001'),'original superseded and retained');
select public.vet_cancel_authorization((select val from vet_ids where key='authorization'));
insert into vet_ids(key,val) select 'blocked_correction',(public.vet_correct_certificate((select val from vet_ids where key='correction'))).id;
select vet_test.denied($q$select public.vet_issue_certificate((select val from vet_ids where key='blocked_correction'))$q$,'VET_PRIOR_AUTHORIZATION_REQUIRED');
select public.vet_delete_draft((select val from vet_ids where key='blocked_correction'));
select vet_test.ok((select count(*)=0 from public.vet_certificates where id=(select val from vet_ids where key='blocked_correction')),'draft deleted');
insert into vet_ids(key,val) values('cancelled',public.vet_request_authorization((select val from vet_ids where key='practitioner'),repeat('b',64),'personal_link','vet@example.test'));
select public.vet_cancel_authorization((select val from vet_ids where key='cancelled'));
insert into vet_ids(key,val) values('expired',public.vet_request_authorization((select val from vet_ids where key='practitioner'),repeat('c',64),'personal_link','vet@example.test'));
reset role;
update public.vet_signature_authorizations set expires_at=now()-interval '1 minute' where id=(select val from vet_ids where key='expired');
select vet_test.denied($q$select public.vet_authorization_summary(repeat('b',64))$q$,'VET_AUTHORIZATION_LINK_INVALID');
select vet_test.denied($q$select public.vet_authorization_summary(repeat('c',64))$q$,'VET_AUTHORIZATION_LINK_INVALID');
select vet_test.ok((select public.vet_public_certificate_status(public_number)->>'status'='valid' from public.vet_certificates where id=(select val from vet_ids where key='correction')),'public page signed status');
select vet_test.ok((select public.vet_public_certificate_status(public_number)->>'status'='superseded' from public.vet_certificates where id='a2000000-0000-0000-0000-000000000001'),'public page correction status');
select vet_test.ok((select public.vet_public_certificate_status(public_number)#>>'{details,owner_name}'=snapshot#>>'{certificate,owner,name}' and public.vet_public_certificate_status(public_number)#>>'{details,horse_name}'=snapshot#>>'{certificate,horse,name}' from public.vet_certificates where id=(select val from vet_ids where key='correction')),'public page uses issued horse and owner snapshot');
select vet_test.ok((select public.vet_public_certificate_status(public_number)#>>'{details,administrations,0,lot}'='LOT-1' from public.vet_certificates where id=(select val from vet_ids where key='correction')),'public page vaccine lot');
select vet_test.ok((select public.vet_public_certificate_status(public_number)::text !~ '(agent@example.test|contact_details|owner_email|agent_email|requested_by|signed_content|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})' from public.vet_certificates where id=(select val from vet_ids where key='correction')),'public page excludes personal contacts, tokens and internal IDs');
select vet_test.ok(public.vet_public_certificate_status('VET-NOT-FOUND') is null,'public unknown number reveals nothing');

set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select vet_test.denied($q$select public.vet_revoke_certificate((select val from vet_ids where key='correction'),'   ')$q$,'VET_REASON_REQUIRED');
select public.vet_revoke_certificate((select val from vet_ids where key='correction'),'test');
select vet_test.ok((select details->>'reason'='test' from public.vet_audit_events where entity_id=(select val from vet_ids where key='correction') and action='revoked'),'short reason accepted and audited');
select vet_test.ok((public.vet_get_certificate_health((select val from vet_ids where key='correction'))#>>'{influenza,status}')<>'valid','revoked and superseded evidence excluded');
select public.vet_admin_save_issuer('a1000000-0000-0000-0000-000000000001','Clinique A','clinic','Québec test','suspended');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select vet_test.ok((select count(*)=0 from public.vet_certificates where issuer_id='a1000000-0000-0000-0000-000000000001'),'suspension immediately removes access');
select vet_test.denied($q$select public.vet_issue_certificate((select val from vet_ids where key='correction'))$q$,'VET_ACCESS_DENIED');
reset role;
select vet_test.ok((select public.vet_public_certificate_status(public_number)->>'status'='revoked' from public.vet_certificates where id=(select val from vet_ids where key='correction')),'public page revoked status even for suspended issuer');
select vet_test.ok((select public.vet_public_certificate_status(public_number)->>'replacement_number' is not null from public.vet_certificates where id='a2000000-0000-0000-0000-000000000001'),'public correction link retained when replacement revoked');
select vet_test.ok(not has_function_privilege('authenticated','public.vet_issue_authorized_internal(uuid)','EXECUTE'),'internal issuer not callable');
select vet_test.ok(not has_function_privilege('service_role','public.vet_issue_authorized_internal(uuid)','EXECUTE'),'worker cannot bypass signature');
select vet_test.ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'vet_%' and p.prosecdef and not ('search_path=""'=any(p.proconfig))),'all privileged functions have controlled search_path');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select public.vet_admin_save_issuer('a1000000-0000-0000-0000-000000000001','Clinique A','clinic','Québec test','active');
select vet_test.denied($q$select public.vet_request_authorization((select val from vet_ids where key='practitioner'),repeat('f',64),'local_test')$q$,'VET_AUTHORIZATION_METHOD_INVALID');
select vet_test.denied($q$select public.vet_create_local_test_authorization('20000000-0000-0000-0000-000000000001',(select val from vet_ids where key='practitioner'),'phase1.org-a-secretary@example.test')$q$,'permission denied');
reset role;
select vet_test.denied($q$select public.vet_create_local_test_authorization('20000000-0000-0000-0000-000000000003',(select val from vet_ids where key='practitioner'),'')$q$,'VET_ADMIN_REQUIRED');
select vet_test.denied($q$select public.vet_create_local_test_authorization('20000000-0000-0000-0000-000000000001',(select val from vet_ids where key='practitioner'),'phase1.org-a-owner@example.test')$q$,'VET_TARGET_ACCOUNT_FORBIDDEN');
insert into vet_ids(key,val) values('test_authorization',public.vet_create_local_test_authorization('20000000-0000-0000-0000-000000000001',(select val from vet_ids where key='practitioner'),'phase1.org-a-secretary@example.test'));
select vet_test.ok((select method='local_test' and requested_by='20000000-0000-0000-0000-000000000003' and valid_until=now()+interval '24 hours' from public.vet_signature_authorizations where id=(select val from vet_ids where key='test_authorization')),'simulation is explicit, scoped and short-lived');
select vet_test.ok(public.vet_create_local_test_authorization('20000000-0000-0000-0000-000000000001',(select val from vet_ids where key='practitioner'),'phase1.org-a-secretary@example.test')=(select val from vet_ids where key='test_authorization'),'simulation creation idempotent');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select public.vet_save_draft('a1000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000009',1,(select val from vet_ids where key='practitioner'),jsonb_set(vet_test.payload(),'{administrations,0,administered_on}',to_jsonb(current_date)));
insert into vet_ids(key,j) values('test_horse_search',public.vet_search_horse_candidates('a2000000-0000-0000-0000-000000000009','Pilot Horse','Pilot Owner','','123456789012345'));
select public.vet_link_horse('a2000000-0000-0000-0000-000000000009',(select (j#>>'{results,0,selection_id}')::uuid from vet_ids where key='test_horse_search'),true);
select public.vet_issue_certificate('a2000000-0000-0000-0000-000000000009');
select vet_test.ok((select (snapshot#>>'{signature,signed_content,test_only}')::boolean from public.vet_certificates where id='a2000000-0000-0000-0000-000000000009'),'test designation bound to issued snapshot');
select vet_test.ok((public.vet_get_certificate_health('a2000000-0000-0000-0000-000000000009')#>>'{influenza,status}')<>'valid','simulation never becomes recognized vaccination');
select vet_test.ok((public.vet_get_certificate_health('a2000000-0000-0000-0000-000000000009')#>>'{influenza,reason}')='test_certificate','simulation exclusion is explained');
select vet_test.ok((select public.vet_public_certificate_status(public_number)->>'status'='test' from public.vet_certificates where id='a2000000-0000-0000-0000-000000000009'),'verification page exposes simulation, not validity');
reset role;

select vet_test.ok(public.vet_claim_omvq_lookup(),'first global worker lookup claimed');
select vet_test.ok(not public.vet_claim_omvq_lookup(),'parallel worker lookup refused');
select vet_test.ok(not has_function_privilege('authenticated','public.vet_claim_omvq_lookup()','execute'),'client cannot reset global throttle');
insert into public.vet_preprod_outbox(id,issuer_id,created_by,recipient,kind,encrypted_message)
values ('a6000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000003','test@example.test','authorization','encrypted-fixture');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select vet_test.ok((select count(id)=1 from public.vet_preprod_outbox),'staff can list own test mail');
select vet_test.denied($q$select encrypted_message from public.vet_preprod_outbox$q$,'permission denied');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
select vet_test.ok((select count(id)=0 from public.vet_preprod_outbox),'ordinary user cannot read test mail');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000006',true);
select vet_test.ok((select count(id)=0 from public.vet_preprod_outbox),'other clinic cannot read test mail');
reset role;
update public.vet_preprod_outbox set expires_at=now()-interval '1 second';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select vet_test.ok((select count(id)=0 from public.vet_preprod_outbox),'expired test mail hidden');
reset role;
rollback;
